import os, re

def load():
    d = os.environ['RLM_SESSION_DIR']
    t = open(d + '/../../sessions/' + os.path.basename(d) + '.jsonl').read()
    G = {}
    matches = list(re.finditer(r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n', t))
    for m in matches:
        k, h, w = m[1], int(m[2]), int(m[3])
        rows_text = t[m.end():].split('\n')[:h]
        if k not in G and all(len(row) == w and all(x.isdigit() for x in row) for row in rows_text):
            G[k] = [[int(x) for x in row] for row in rows_text]
    return G

G = load()
print("Grids loaded:", sorted(G.keys()))
for k, grid in G.items():
    print(f"{k}: {len(grid)}x{len(grid[0])}")

