with open(log_path) as f:
    content = f.read()

# Parse grids
grid_pattern = r'(Demo pair \d+ (?:input|output)|Test input) \((\d+)x(\d+)\):\n((?:\d+\s+(?:\d+\s+)+)\n)+'

G = {}
for m in re.finditer(grid_pattern, content):
    label = m[1]
    h, w = int(m[2]), int(m[3])
    rows_text = m[4].strip().split('\n')[:h]
    G[label] = [[int(x) for x in row.split()] for row in rows_text]

print("Grids loaded:")
for k, grid in G.items():
    print(f"  {k}: {len(grid)}x{len(grid[0])}")

def find_4_regions(grid):
    """Find connected components of 4s using 4-connectivity"""
    rows, cols = len(grid), len(grid[0])
    visited = set()
    components = []

    def get_component(i, j):
        component = [(i, j)]
        stack = [(i, j)]
        seen = {(i, j)}
        while stack:
            ni, nj = stack.pop()
            for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                ni2, nj2 = ni + di, nj + dj
                if 0 <= ni2 < rows and 0 <= nj2 < cols:
                    if grid[ni2][nj2] == 4 and (ni2, nj2) not in seen:
                        seen.add((ni2, nj2))
                        stack.append((ni2, nj2))
                        component.append((ni2, nj2))
        return component

    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 4 and (i,j) not in visited:
                comp = get_component(i, j)
                for c in comp:
                    visited.add(c)
                components.append(comp)
    return components

# Analyze demo inputs
for name, grid in ['demo1_input', 'demo2_input']:
    g = G.get(name)
    if g:
        comps = find_4_regions(g)
        print(f"\n{name}: {len(comps)} components")
        for i, comp in enumerate(comps):
            size = len(comp)
            min_r = min(r for r,c in comp)
            max_r = max(r for r,c in comp)
            min_c = min(c for r,c in comp)
            max_c = max(c for r,c in comp)
            print(f"  Comp {i}: size={size}, bbox=[{min_r},{min_c}]-[{max_r},{max_c}]")

# Find isolated 4s (single pixel regions)
def count_single_4s(grid):
    rows, cols = len(grid), len(grid[0])
    visited = set()
    singles = 0
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 4 and (i,j) not in visited:
                # Check if this is an isolated cell (no 4 neighbors)
                neighbors_4 = 0
                for di, dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                    ni, nj = i + di, j + dj
                    if 0 <= ni < rows and 0 <= nj < cols and grid[ni][nj] == 4:
                        neighbors_4 += 1
                if neighbors_4 == 0:
                    singles += 1
                    visited.add((i,j))
                else:
                    # Part of component
                    visited.add((i,j))
    return singles

for name, grid in ['demo1_input', 'demo2_input']:
    g = G.get(name)
    if g:
        single_count = count_single_4s(g)
        print(f"\n{name} single isolated 4s: {single_count}")

