def apply_transform(grid):
    """Apply the suspected transform: single isolated 4s become 1s, keep connected 4s"""
    rows, cols = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find all 4s and their connectivity
    visited = set()
    for i in range(rows):
        for j in range(cols):
            if grid[i][j] == 4 and (i,j) not in visited:
                # BFS to find component
                comp = []
                stack = [(i,j)]
                seen = {(i,j)}
                while stack:
                    ni, nj = stack.pop()
                    comp.append((ni,nj))
                    for di,dj in [(-1,0),(1,0),(0,-1),(0,1)]:
                        ni2, nj2 = ni + di, nj + dj
                        if 0 <= ni2 < rows and 0 <= nj2 < cols:
                            if grid[ni2][nj2] == 4 and (ni2,nj2) not in seen:
                                seen.add((ni2,nj2))
                                stack.append((ni2,nj2))
                # If component has size 1, change to 1
                if len(comp) == 1:
                    ri, rj = comp[0]
