def get_region_boundaries(grid, value, bg):
    """Find all boundary cells of a region (cells with non-bg neighbors outside the region)"""
    rows, cols = len(grid), len(grid[0])
    boundaries = []

    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == value:
                # Check if any non-bg neighbor exists
