                for dr, dc in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < rows and 0 <= nc < cols:
                        if grid[nr][nc] != bg:
                            has_non_bg_neighbor = True
                            break

                if has_non_bg_neighbor:
                    boundaries.append((r, c))

    return boundaries

